"use strict";(self.webpackChunkibm_gantt_chart_docs=self.webpackChunkibm_gantt_chart_docs||[]).push([[706],{"./src/docs/timeLine.stories.js"(__unused_webpack_module,__webpack_exports__,__webpack_require__){__webpack_require__.r(__webpack_exports__),__webpack_require__.d(__webpack_exports__,{ActivitiesLayout:()=>ActivitiesLayout,ActivityRendering:()=>ActivityRendering,DecorationsBreak:()=>DecorationsBreak,DragNDrop:()=>DragNDrop,Overview:()=>Overview,__namedExportsOrder:()=>__namedExportsOrder,default:()=>timeLine_stories});var marked_esm=__webpack_require__("../../node_modules/marked/lib/marked.esm.js");__webpack_require__("./src/docs/github-markdown.css");const renderMarkdown=md=>`<div class="markdown-body" style="margin: 1rem;">${marked_esm.xI.parse(md)}</div>`,timeLine_stories={title:"Guides/Time Line",parameters:{storySource:{source:"import { marked } from 'marked';\n\nimport activitiesLayout from './time_line_activities_layout.md';\nimport activityRendering from './time_line_activity_rendering.md';\nimport decorations from './time_line_decorations.md';\nimport dragDrop from './time_line_dragdrop.md';\nimport overview from './time_line_overview.md';\n\nimport './github-markdown.css';\n\nconst renderMarkdown = (md) => `<div class=\"markdown-body\" style=\"margin: 1rem;\">${marked.parse(md)}</div>`;\n\nexport default {\n  title: 'Guides/Time Line',\n  parameters: { options: { showPanel: false } },\n};\n\nexport const Overview = {\n  render: () => renderMarkdown(overview),\n};\n\nexport const ActivityRendering = {\n  render: () => renderMarkdown(activityRendering),\n};\n\nexport const ActivitiesLayout = {\n  render: () => renderMarkdown(activitiesLayout),\n};\n\nexport const DecorationsBreak = {\n  render: () => renderMarkdown(decorations),\n};\n\nexport const DragNDrop = {\n  render: () => renderMarkdown(dragDrop),\n};\n",locationsMap:{overview:{startLoc:{col:24,line:18},endLoc:{col:1,line:20},startBody:{col:24,line:18},endBody:{col:1,line:20}},"activity-rendering":{startLoc:{col:33,line:22},endLoc:{col:1,line:24},startBody:{col:33,line:22},endBody:{col:1,line:24}},"activities-layout":{startLoc:{col:32,line:26},endLoc:{col:1,line:28},startBody:{col:32,line:26},endBody:{col:1,line:28}},"decorations-break":{startLoc:{col:32,line:30},endLoc:{col:1,line:32},startBody:{col:32,line:30},endBody:{col:1,line:32}},"drag-n-drop":{startLoc:{col:25,line:34},endLoc:{col:1,line:36},startBody:{col:25,line:34},endBody:{col:1,line:36}}}},options:{showPanel:!1}}},Overview={render:()=>renderMarkdown("# Timeline\n\nThe timeline is the right panel of a Gantt chart displaying activities in a timeline as illustrated in:\n\n![alt text](/images/doc/concepts_schedule_chart.jpg 'Timeline')\n\nAs for all Gantt components, the timeline can initialize without any configuration from the user.\nBut it can be customized in many ways:\n\n- [Activity rendering](#?path=/story/guides-time-line--activity-rendering), to customize the display of activities to reflect user model properties.\n- [Activities layout](./?path=/story/guides-time-line--activities-layout), to change the layout of activities, typically when several activities in the same row have the same start time.\n- [Add decorations/breaks](./?path=/story/guides-time-line--decorations), to add decorations, breaks, or time markers in the time line.\n- [Drag and drop of activities](./?path=/story/guides-time-line--drag-n-drop, to implement the drag-and-drop of activities.\n")},ActivityRendering={render:()=>renderMarkdown("# Rendering of activities\n\nChanging the default display of activities to reflect properties of the user model is one of the most important features of the Gantt chart.\nThis can be done by declaring one or several [renderers](./?path=/story/guides-miscellaneous--renderers) in the `timeTable.renderer` Gantt configuration.\nSee [common renderer properties](./?path=/story/guides-miscellaneous--renderers) for the list of properties that can be used.\n\nHere is a code extract from the [House building](/examples/house_building.html) sample that combines renderer cascading and the use of palettes features:\n\n```\n    var ganttConfig = {\n            ...\n            timeTable : {\n                renderer : [\n                    {\n                        selector : function(object, ctx) {\n                            // Use this renderer if the display mode combobox is selected on 'Tasks'\n                            return ctx.gantt.colorMode === 'showTasks'\n                        },\n                        text : function(activity) { // Instead of using a function, the text property could have been declared as: text : \"TASK.NAME\"\n                            return activity.TASK.NAME;\n                        },\n                        textOverflow : 'noDisplay', // Hide the text if it doesn't fit the width of the activity rectangle\n                        background : {\n                            // Uncomment line below to fix the index order of task names and therefore ensure tasks will always be displayed with the same color.\n                            //values : [ 'facade', 'ceiling', 'windows', 'moving', 'masonry', 'carpentry', 'roofing', 'plumbing', 'painting', 'garden' ],\n                            // Uncomment line below for using a palette replacement from the default Gantt palette.\n                            //palette : [\"#a6cee3\", \"#1f78b4\", \"#b2df8a\", \"#33a02c\", \"#fb9a99\", \"#e31a1c\", \"#fdbf6f\", \"#ff7f00\", \"#cab2d6\", \"#6a3d9a\"],\n                            getValue : 'TASK.NAME'\n                        },\n                        color : 'automatic', // Text color will be white or black depending on the background color of the activity rectangle.\n                        tooltipProperties : function(activity, ctx) {\n                            var props = [ 'Start', new Date(activity.start).format(), 'End', new Date(activity.end).format()];\n                            // Create a large amount of tooltip properties to demonstrate how the tooltip behaves on large property numbers.\n                            for(var i = 0; i < 50; i++) {\n                                props.push('Property ' + (i + 1));\n                                props.push('Value ' + (i + 1));\n                            }\n                            return props;\n                        }\n                    }, {\n                        selector : function(object, ctx) {\n                            // Use this renderer if the display mode combobox is selected on 'Houses'\n                            return ctx.gantt.colorMode === 'showHouses'\n                        },\n                        text : function(activity) {\n                            return \"H\" + activity.HOUSE;\n                        },\n                        background : {\n                            values : function(object, ctx) {\n                                return Object.keys(ctx.gantt.houseTimeWindows);\n                            },\n                            // Default palette is used\n                            getValue : 'HOUSE' // Access the HOUSE field of provided activity. eq to function(act) { return act.HOUSE; }\n                        },\n                        color : 'automatic' // Text color will be white or black depending on the background color of the activity rectangle.\n                    }, {\n                        selector : function(object, ctx) {\n                            // Use this renderer if the display mode combobox is selected on 'All'\n                            return ctx.gantt.colorMode === 'showAll'\n                        },\n                        text : function(activity) {\n                            return \"H\" + activity.HOUSE + '-' + activity.TASK.NAME;\n                        },\n                        background : {\n                            values : function(object, row) {\n                                return Object.keys(row.gantt.houseTimeWindows);\n                            },\n                            getValue : 'HOUSE'\n                        },\n                        color : 'automatic' // Text color will be white or black depending on the background color of the activity rectangle.\n                    }\n                 ]\n            }\n            ...\n        }\n        new Gantt( 'gantt', ganttConfig );\n```\n\n<a id=\"activityrenderer_callbacks\"></a>\n\n#### Callbacks\n\nAll renderer properties can be defined as function callbacks to fetch display properties according to dynamic user model properties.\nFunctions will be called providing as the parameters:\n\n- The Gantt reservation or activity being rendered, depending on whether the Gantt chart is a Schedule chart or Activity chart.\n  In the House building sample previously illustrated, the passed object is a Gantt reservation associated with the assignments of the user model.\n- The Gantt resource or Gantt activity containing the activity being rendered, depending on whether the Gantt is a Schedule chart or Activity chart.\n\nSee [Binding of user and Gantt data](./?path=/story/guides-data--overview) for details on how to access user model object through Gantt model objects.\n")},ActivitiesLayout={render:()=>renderMarkdown("# Layout of activities\n\nIn the timetable, activities are positioned on the horizontal time axis according to the start and end property of the activity.\nBy default, activities fit the height of their containing row, minus a vertical padding.\n\nThis is usually fine for most user models when a resource can only perform one activity at a time.\nFor models with resources having parallel activities, however, activities can be partially or fully hidden as all activities in a same row have the same vertical position and a same height.\n\nTo avoid this behavior, the Gantt configuration allows you to change the activity layout to vertically display the activities differently.\n\nTwo alternative activity layouts can be used:\n\n1. Logistic layout\n\n   Parallel activities in a same resource are cascaded vertically. This layout does not impact the height of the resource row.\n\n![alt text](/images/doc/logistic-layout.png 'Logistic layout')\n\n2. Tile layout\n\n   Parallel activities are vertically stacked on top each others. This layout does impact the height of the resource row.\n\n![alt text](/images/doc/tile-layout.png 'Tile layout')\n\nThe activity layout is specified with the Gantt configuration `timeTable.layout.strategy` which can be given a `string` that identifies the layout to use or a function returning the same `string`.\n\n- Use the `string` value `\"logistic\"` for logistic layout.\n- Use the `string` value `\"tile\"` for tile layout.\n- Use an empty `string` value for the default activity layout.\n\nThis code extract is from the [row layout](/examples/rowlayout.html) example that illustrates the change of activity layout with a function:\n\n```\n    var config {\n        ...\n        timeTable: {\n            layout: {\n                strategy: function (ctx) {\n                    return ctx.gantt.rowLayoutMode; // Returns either an empty string\n                }\n            }\n    ...\n```\n")},DecorationsBreak={render:()=>renderMarkdown("# Add decorations and breaks to the time line\n\nThe display of timelines can be customized to add different types of visual elements to provide useful information relative to time for the user model such as:\n\n- Show invalid time zones in which no activity can be performed. This use done by generating global decorations to the time line.\n- For each resource, show time frames when the resource cannot perform any activities (breaks). This is done by generating time decorations local to a specific resource.\n- Show time markers on the time axis for important dates of the schedule, such as the start date of a project. An API is provided for adding time markers.\n- Show time frame markers on the time axis to highlight specific time periods. An API is provided for adding time zone markers.\n\n### Decorations.\n\nDecorations are gray zones displayed in the background of activities to show information such as breaks for a resource or time zones when no activity can be performed.\nDecorations can be global to the time line or local to a resource. They have to predefined types:\n\n- Invalid, displayed by default as an hatched area:\n\n![alt text](/images/doc/decoration-invalid.png 'Invalid zone')\n\n- Break, displayed by default a solid gray area:\n\n![alt text](/images/doc/decoration-break.png 'Break zone')\n")},DragNDrop={render:()=>renderMarkdown("# Drag and drop of activities\n\nTODO...\n")},__namedExportsOrder=["Overview","ActivityRendering","ActivitiesLayout","DecorationsBreak","DragNDrop"];Overview.parameters={...Overview.parameters,docs:{...Overview.parameters?.docs,source:{originalSource:"{\n  render: () => renderMarkdown(overview)\n}",...Overview.parameters?.docs?.source}}},ActivityRendering.parameters={...ActivityRendering.parameters,docs:{...ActivityRendering.parameters?.docs,source:{originalSource:"{\n  render: () => renderMarkdown(activityRendering)\n}",...ActivityRendering.parameters?.docs?.source}}},ActivitiesLayout.parameters={...ActivitiesLayout.parameters,docs:{...ActivitiesLayout.parameters?.docs,source:{originalSource:"{\n  render: () => renderMarkdown(activitiesLayout)\n}",...ActivitiesLayout.parameters?.docs?.source}}},DecorationsBreak.parameters={...DecorationsBreak.parameters,docs:{...DecorationsBreak.parameters?.docs,source:{originalSource:"{\n  render: () => renderMarkdown(decorations)\n}",...DecorationsBreak.parameters?.docs?.source}}},DragNDrop.parameters={...DragNDrop.parameters,docs:{...DragNDrop.parameters?.docs,source:{originalSource:"{\n  render: () => renderMarkdown(dragDrop)\n}",...DragNDrop.parameters?.docs?.source}}}}}]);
